std::pair<int, int> two_sum(const std::vector<int>& v, int target) {
    std::vector<std::pair<int, int>> pairs;
    for (int i = 0; i < v.size(); ++i) {
        for (int j = i + 1; j < v.size(); ++j) {
            if (v[i] + v[j] == target) {
                pairs.push_back({i, j});
            }
        }
    }
    if (pairs.empty()) return {-1, -1};
    std::sort(pairs.begin(), pairs.end());
    return pairs[0];
}

